mapper.select:
select d.detail_id
from order_detail d
join orders o on d.order_id = o.order_id
where o.user_id = #{userId}
	and d.item_id = #{itemId}
	and (d.detail_review = false or d.detail_review is null)
order by d.detail_id desc
limit 1;

mapper.update:
update order_detail
set detail_review = true
where detail_id = #{detailId}
	and (detail_review = false or detail_review is null);
